def parse_pairs(s):
    pairs = {}
    for part in [p for p in s.split(';') if p.strip()]:
        key, rest = part.split('=', 1)
        key = key.strip()
        if rest.startswith("'"):
            value = rest[1:].split("'", 1)[0]
        else:
            value = rest.strip()
        pairs[key] = value
    return pairs
