from collections import defaultdict

class Limiter:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.cache = defaultdict(list)

    def hit(self, key, now):
        # 移除窗口外的记录
        self.cache[key] = [t for t in self.cache[key] if t >= now - self.window]
        # 统计当前窗口内的命中次数
        count = sum(1 for t in self.cache[key] if now - self.window <= t < now)
        if count < self.limit:
            self.cache[key].append(now)
            return True
        return False

    def count(self, key, now):
        # 返回当前窗口内的命中次数（不记录本次）
        return sum(1 for t in self.cache[key] if now - self.window <= t < now)
